SELECT d.id, 'en', 'Mandatory content', '[["Standard particulars","Both parties, the invoice number and date, a description of the supply, and the net amount, VAT rate and VAT due for each rate."],["Four additions for 2026","A SIREN for supplier and customer, a delivery address where it differs, whether the supply is goods, services or both, and a VAT-on-debits mention."],["When the four bite","Invoices issued from 1 September 2026 for large and mid-sized firms, and from 1 September 2027 for micro and small ones."],["The legal list is not the file","What is transmitted is both narrower and broader than the legal list: no line description, but commercial-code mentions on top, fixed by arrêté."]]', 'Legifrance''s consolidated article already shows the four new mentions, under a banner reading "in force since 01/01/2025". The commencement rule is not in the code — it is in article 3 of décret 2022-1299.', NULL FROM deep_dive_cards d WHERE d.country_id = (SELECT id FROM countries WHERE name_en = 'France') AND d.section = 'file_format' AND d.sort_order = 2;
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body)
SELECT d.id, 'es', 'Contenido obligatorio', '[["Menciones estándar","Ambas partes, el número y la fecha de la factura, una descripción de la operación, y la base, el tipo de IVA y la cuota por cada tipo."],["Cuatro añadidos para 2026","Un SIREN para proveedor y cliente, la dirección de entrega si difiere, si la operación es de bienes, servicios o ambos, y la mención de IVA por débitos."],["Cuándo se aplican","A las facturas emitidas desde el 1 de septiembre de 2026 para las grandes y medianas empresas, y desde el 1 de septiembre de 2027 para las micro y pequeñas."],["La lista legal no es el fichero","Lo transmitido es más estrecho y más amplio que la lista legal: sin descripción de línea, pero con menciones del código de comercio, fijadas por arrêté."]]', 'El artículo consolidado de Legifrance ya muestra las cuatro nuevas menciones, bajo un aviso de «en vigor desde el 01/01/2025». La norma de entrada en vigor no está en el código, sino en el artículo 3 del décret 2022-1299.', NULL FROM deep_dive_cards d WHERE d.country_id = (SELECT id FROM countries WHERE name_en = 'France') AND d.section = 'file_format' AND d.sort_order = 2;
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body)
SELECT d.id, 'de', 'Pflichtangaben', '[["Standardangaben","Beide Parteien, Rechnungsnummer und -datum, eine Beschreibung der Leistung sowie Nettobetrag, Steuersatz und Steuerbetrag je Satz."],["Vier Ergänzungen ab 2026","Eine SIREN für Lieferant und Kunde, eine abweichende Lieferadresse, ob Waren, Dienstleistungen oder beides geliefert wird, und ein Hinweis zur Debitorenbesteuerung."],["Ab wann sie gelten","Für Rechnungen ab dem 1. September 2026 bei großen und mittleren Unternehmen, und ab dem 1. September 2027 bei Kleinst- und Kleinunternehmen."],["Die Rechtsliste ist nicht die Datei","Übermittelt wird zugleich weniger und mehr als die Rechtsliste: keine Positionsbeschreibung, dafür Angaben aus dem Handelsgesetzbuch, per Arrêté festgelegt."]]', 'Der konsolidierte Artikel auf Legifrance zeigt die vier neuen Angaben bereits, unter dem Hinweis „in Kraft seit 01.01.2025“. Die Inkrafttretensregel steht nicht im Gesetzbuch, sondern in Artikel 3 des Décret 2022-1299.', NULL FROM deep_dive_cards d WHERE d.country_id = (SELECT id FROM countries WHERE name_en = 'France') AND d.section = 'file_format' AND d.sort_order = 2;
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body)
SELECT d.id, 'fr', 'Mentions obligatoires', '[["Mentions standard","Les deux parties, le numéro et la date de la facture, une description de l''opération, et le montant hors taxe, le taux et la TVA due par taux."],["Quatre ajouts pour 2026","Un SIREN pour le fournisseur et le client, l''adresse de livraison si elle diffère, la nature de l''opération, et la mention de l''option pour les débits."],["Quand elles s''appliquent","Aux factures émises à compter du 1er septembre 2026 pour les grandes et moyennes entreprises, et du 1er septembre 2027 pour les micro et petites."],["La liste légale n''est pas le fichier","Ce qui est transmis est à la fois plus étroit et plus large que la liste légale : pas de description de ligne, mais des mentions du code de commerce."]]', 'L''article consolidé sur Legifrance affiche déjà les quatre nouvelles mentions, sous un bandeau « en vigueur depuis le 01/01/2025 ». La règle d''entrée en vigueur n''est pas dans le code : elle est à l''article 3 du décret 2022-1299.', NULL FROM deep_dive_cards d WHERE d.country_id = (SELECT id FROM countries WHERE name_en = 'France') AND d.section = 'file_format' AND d.sort_order = 2;
