SELECT d.id, 'en', 'Mandatory content', '[["No prescribed document","Since 1 April 2023 no tax-invoice document is required. The duty is to hold set GST details, which several records may carry between them."],["What the tiers change","At NZD 200 or less nothing need be given to the buyer. Above NZD 200 add the seller''s GST number; above NZD 1,000 add buyer identification."],["Buyer''s GST number","Rarely needed. Above NZD 1,000 give the buyer''s name and one identifier — an address, email or NZBN. Buyer-created records need both numbers."],["Peppol changes nothing","The content rule is format-neutral. A Peppol invoice can carry it, and adds no GST field of its own."]]', 'Read from Inland Revenue''s own guidance, not from the Act: legislation.govt.nz refused every request. The section numbers behind these rules are therefore uncited here.', NULL FROM deep_dive_cards d WHERE d.country_id = (SELECT id FROM countries WHERE name_en = 'New Zealand') AND d.section = 'file_format' AND d.sort_order = 2;
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body)
SELECT d.id, 'es', 'Contenido obligatorio', '[["Ningún documento prescrito","Desde el 1 de abril de 2023 no se exige un documento de factura fiscal. El deber es conservar ciertos datos de GST, que varios registros pueden repartirse."],["Qué cambian los tramos","Hasta 200 NZD no hay que entregar nada al comprador. Por encima de 200 NZD se añade el número de GST del vendedor; por encima de 1.000 NZD, la identificación del comprador."],["Número de GST del comprador","Rara vez necesario. Por encima de 1.000 NZD, el nombre del comprador y un identificador: dirección, correo o NZBN. Los registros creados por el comprador exigen ambos números."],["Peppol no cambia nada","La regla de contenido es neutral respecto al formato. Una factura Peppol puede llevarla, y no añade ningún campo de GST propio."]]', 'Tomado de la guía de Inland Revenue, no de la ley: legislation.govt.nz rechazó todas las peticiones. Por eso no se citan aquí los números de artículo.', NULL FROM deep_dive_cards d WHERE d.country_id = (SELECT id FROM countries WHERE name_en = 'New Zealand') AND d.section = 'file_format' AND d.sort_order = 2;
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body)
SELECT d.id, 'de', 'Pflichtangaben', '[["Kein vorgeschriebenes Dokument","Seit dem 1. April 2023 ist kein Steuerrechnungsdokument vorgeschrieben. Zu halten sind bestimmte GST-Angaben, die sich auf mehrere Belege verteilen dürfen."],["Was die Stufen ändern","Bis 200 NZD muss dem Käufer nichts ausgehändigt werden. Über 200 NZD kommt die GST-Nummer des Verkäufers hinzu, über 1.000 NZD die Identifikation des Käufers."],["GST-Nummer des Käufers","Selten erforderlich. Über 1.000 NZD Name des Käufers plus eine Kennung: Adresse, E-Mail oder NZBN. Vom Käufer erstellte Belege brauchen beide Nummern."],["Peppol ändert nichts","Die Inhaltsregel ist formatneutral. Eine Peppol-Rechnung kann sie tragen und fügt kein eigenes GST-Feld hinzu."]]', 'Aus der Anleitung von Inland Revenue entnommen, nicht aus dem Gesetz: legislation.govt.nz hat jede Anfrage abgewiesen. Die Paragraphennummern sind daher hier nicht zitiert.', NULL FROM deep_dive_cards d WHERE d.country_id = (SELECT id FROM countries WHERE name_en = 'New Zealand') AND d.section = 'file_format' AND d.sort_order = 2;
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body)
SELECT d.id, 'fr', 'Mentions obligatoires', '[["Aucun document prescrit","Depuis le 1er avril 2023, aucun document de facture fiscale n''est exigé. L''obligation est de détenir certaines données de GST, que plusieurs pièces peuvent porter ensemble."],["Ce que changent les seuils","Jusqu''à 200 NZD, rien n''a à être remis à l''acheteur. Au-delà de 200 NZD s''ajoute le numéro de GST du vendeur ; au-delà de 1 000 NZD, l''identification de l''acheteur."],["Numéro de GST de l''acheteur","Rarement requis. Au-delà de 1 000 NZD, le nom de l''acheteur et un identifiant : adresse, courriel ou NZBN. Les pièces établies par l''acheteur exigent les deux numéros."],["Peppol ne change rien","La règle de contenu est neutre quant au format. Une facture Peppol peut la porter et n''ajoute aucun champ de GST propre."]]', 'Établi d''après les instructions d''Inland Revenue et non d''après la loi : legislation.govt.nz a refusé chaque requête. Les numéros d''article ne sont donc pas cités ici.', NULL FROM deep_dive_cards d WHERE d.country_id = (SELECT id FROM countries WHERE name_en = 'New Zealand') AND d.section = 'file_format' AND d.sort_order = 2;
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'file_format', 3 FROM countries WHERE name_en = 'New Zealand';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body)
SELECT d.id, 'en', 'Archiving', '[["Period and basis","At least seven tax years, and the duty covers electronic records on the same footing as paper — there is no separate, lighter rule for a digital original."],["Retention","7 years"],["Signature","Not required for the archived copy. Integrity rests on ordinary bookkeeping controls rather than on a certificate."]]', NULL, NULL FROM deep_dive_cards d WHERE d.country_id = (SELECT id FROM countries WHERE name_en = 'New Zealand') AND d.section = 'file_format' AND d.sort_order = 3;
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body)
SELECT d.id, 'es', 'Conservación', '[["Plazo y fundamento","Al menos siete ejercicios fiscales, y el deber alcanza a los registros electrónicos en igualdad con el papel: no hay una regla aparte y más suave para el original digital."],["Conservación","7 años"],["Firma","No exigida para la copia archivada. La integridad descansa en los controles contables ordinarios, no en un certificado."]]', NULL, NULL FROM deep_dive_cards d WHERE d.country_id = (SELECT id FROM countries WHERE name_en = 'New Zealand') AND d.section = 'file_format' AND d.sort_order = 3;
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body)
SELECT d.id, 'de', 'Aufbewahrung', '[["Frist und Grundlage","Mindestens sieben Steuerjahre, und die Pflicht erfasst elektronische Aufzeichnungen gleichrangig mit Papier — eine gesonderte, mildere Regel für das digitale Original gibt es nicht."],["Aufbewahrung","7 Jahre"],["Signatur","Für die archivierte Kopie nicht erforderlich. Die Integrität stützt sich auf gewöhnliche Buchführungskontrollen, nicht auf ein Zertifikat."]]', NULL, NULL FROM deep_dive_cards d WHERE d.country_id = (SELECT id FROM countries WHERE name_en = 'New Zealand') AND d.section = 'file_format' AND d.sort_order = 3;
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body)
SELECT d.id, 'fr', 'Conservation', '[["Durée et fondement","Au moins sept années fiscales, et l''obligation vise les documents électroniques au même titre que le papier : il n''existe pas de règle distincte et plus souple pour l''original numérique."],["Conservation","7 ans"],["Signature","Non exigée pour la copie archivée. L''intégrité repose sur les contrôles comptables ordinaires, non sur un certificat."]]', NULL, NULL FROM deep_dive_cards d WHERE d.country_id = (SELECT id FROM countries WHERE name_en = 'New Zealand') AND d.section = 'file_format' AND d.sort_order = 3;
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'file_format', 4 FROM countries WHERE name_en = 'New Zealand';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body)
SELECT d.id, 'en', 'What the 2027 mandate covers', '[["Applies to","Domestic trade invoices in NZD only"],["Excludes","International suppliers, cross-border invoicing"],["Tax reporting","GST continues via periodic returns"]]', 'If a New Zealand government contract has any cross-border element, check whether the specific invoice line falls inside this mandate. And unlike Ireland or France, no reporting layer is bolted on — this is an exchange format, not tax-administration reform.', NULL FROM deep_dive_cards d WHERE d.country_id = (SELECT id FROM countries WHERE name_en = 'New Zealand') AND d.section = 'file_format' AND d.sort_order = 4;
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body)
SELECT d.id, 'es', 'Qué cubre el mandato de 2027', '[["Se aplica a","Facturas comerciales nacionales solo en NZD"],["Excluye","Proveedores internacionales, facturación transfronteriza"],["Reporte fiscal","El GST continúa mediante declaraciones periódicas"]]', 'Si un contrato con el gobierno neozelandés tiene algún elemento transfronterizo, compruebe si esa línea de factura concreta queda dentro del mandato. Y a diferencia de Irlanda o Francia, no se le añade ninguna capa de reporte: es un formato de intercambio, no una reforma de la administración tributaria.', NULL FROM deep_dive_cards d WHERE d.country_id = (SELECT id FROM countries WHERE name_en = 'New Zealand') AND d.section = 'file_format' AND d.sort_order = 4;
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body)
SELECT d.id, 'de', 'Was das Mandat von 2027 abdeckt', '[["Gilt für","Nur inländische Handelsrechnungen in NZD"],["Ausgenommen","Internationale Lieferanten, grenzüberschreitende Rechnungsstellung"],["Steuermeldung","GST läuft weiterhin über periodische Erklärungen"]]', 'Enthält ein neuseeländischer Regierungsvertrag ein grenzüberschreitendes Element, prüfen Sie, ob die konkrete Rechnungszeile unter dieses Mandat fällt. Und anders als in Irland oder Frankreich kommt keine Meldeebene hinzu — es geht um ein Austauschformat, nicht um eine Reform der Steuerverwaltung.', NULL FROM deep_dive_cards d WHERE d.country_id = (SELECT id FROM countries WHERE name_en = 'New Zealand') AND d.section = 'file_format' AND d.sort_order = 4;
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body)
SELECT d.id, 'fr', 'Ce que couvre le mandat de 2027', '[["S''applique à","Factures commerciales nationales en NZD uniquement"],["Exclut","Fournisseurs internationaux, facturation transfrontalière"],["Déclaration fiscale","La GST continue via des déclarations périodiques"]]', 'Si un contrat avec le gouvernement néo-zélandais comporte un élément transfrontalier, vérifiez si la ligne de facture concernée relève de ce mandat. Et contrairement à l''Irlande ou à la France, aucune couche de déclaration n''y est greffée : c''est un format d''échange, pas une réforme de l''administration fiscale.', NULL FROM deep_dive_cards d WHERE d.country_id = (SELECT id FROM countries WHERE name_en = 'New Zealand') AND d.section = 'file_format' AND d.sort_order = 4;

-- ---- Norway: 11 rows -> 3/2/4/2 plus one card kept whole ----
DELETE FROM deep_dive_card_translations WHERE card_id IN (SELECT d.id FROM deep_dive_cards d JOIN countries c ON c.id = d.country_id WHERE c.name_en = 'Norway' AND d.section = 'file_format');
DELETE FROM deep_dive_cards WHERE section = 'file_format' AND country_id = (SELECT id FROM countries WHERE name_en = 'Norway');
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'file_format', 0 FROM countries WHERE name_en = 'Norway';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body)
SELECT d.id, 'en', 'Format & standard', '[["Domestic format","EHF 3.0 (Elektronisk Handelsformat)"],["Underlying standard","Peppol BIS Billing 3.0 / UBL, EN 16931"],["Cross-border","Peppol BIS accepted directly"]]', 'EHF is typically used for domestic transactions while Peppol BIS handles both domestic and cross-border — for compliance purposes, both satisfy the legal requirement equally.', NULL FROM deep_dive_cards d WHERE d.country_id = (SELECT id FROM countries WHERE name_en = 'Norway') AND d.section = 'file_format' AND d.sort_order = 0;
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body)
SELECT d.id, 'es', 'Formato y estándar', '[["Formato nacional","EHF 3.0 (Elektronisk Handelsformat)"],["Estándar subyacente","Peppol BIS Billing 3.0 / UBL, EN 16931"],["Transfronterizo","Peppol BIS aceptado directamente"]]', 'EHF se utiliza normalmente para transacciones nacionales, mientras que Peppol BIS gestiona tanto las transacciones nacionales como las transfronterizas — a efectos de cumplimiento, ambos satisfacen el requisito legal por igual.', NULL FROM deep_dive_cards d WHERE d.country_id = (SELECT id FROM countries WHERE name_en = 'Norway') AND d.section = 'file_format' AND d.sort_order = 0;
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body)
SELECT d.id, 'de', 'Format und Standard', '[["Nationales Format","EHF 3.0 (Elektronisk Handelsformat)"],["Zugrunde liegender Standard","Peppol BIS Billing 3.0 / UBL, EN 16931"],["Grenzüberschreitend","Peppol BIS wird direkt akzeptiert"]]', 'EHF wird typischerweise für inländische Transaktionen verwendet, während Peppol BIS sowohl inländische als auch grenzüberschreitende Transaktionen abdeckt — für Konformitätszwecke erfüllen beide die gesetzliche Anforderung gleichermaßen.', NULL FROM deep_dive_cards d WHERE d.country_id = (SELECT id FROM countries WHERE name_en = 'Norway') AND d.section = 'file_format' AND d.sort_order = 0;
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body)
SELECT d.id, 'fr', 'Format et norme', '[["Format national","EHF 3.0 (Elektronisk Handelsformat)"],["Norme sous-jacente","Peppol BIS Billing 3.0 / UBL, EN 16931"],["Transfrontalier","Peppol BIS accepté directement"]]', 'EHF est généralement utilisé pour les transactions nationales tandis que Peppol BIS couvre à la fois les transactions nationales et transfrontalières — à des fins de conformité, les deux satisfont également à l''exigence légale.', NULL FROM deep_dive_cards d WHERE d.country_id = (SELECT id FROM countries WHERE name_en = 'Norway') AND d.section = 'file_format' AND d.sort_order = 0;
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'file_format', 1 FROM countries WHERE name_en = 'Norway';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body)
SELECT d.id, 'en', 'Identifiers & registration', '[["Participant scheme","0192 (ICD code for Norwegian organisasjonsnummer)"],["Common shorthand","\"0192\" and \"NO ORGNR\" in vendor documentation"]]', 'Routing identity ties directly to the organisation number — get this field wrong and delivery simply fails, regardless of how correct the rest of the invoice is.', NULL FROM deep_dive_cards d WHERE d.country_id = (SELECT id FROM countries WHERE name_en = 'Norway') AND d.section = 'file_format' AND d.sort_order = 1;
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body)
SELECT d.id, 'es', 'Identificadores y registro', '[["Esquema de participante","0192 (código ICD para el organisasjonsnummer noruego)"],["Abreviatura habitual","\"0192\" y \"NO ORGNR\" en la documentación de proveedores"]]', 'La identidad de enrutamiento está vinculada directamente al número de organización — si este campo es incorrecto, la entrega simplemente falla, sin importar lo correcto que sea el resto de la factura.', NULL FROM deep_dive_cards d WHERE d.country_id = (SELECT id FROM countries WHERE name_en = 'Norway') AND d.section = 'file_format' AND d.sort_order = 1;
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body)
SELECT d.id, 'de', 'Kennungen und Registrierung', '[["Teilnehmerschema","0192 (ICD-Code für die norwegische organisasjonsnummer)"],["Gängige Kurzform","\"0192\" und \"NO ORGNR\" in der Anbieterdokumentation"]]', 'Die Routing-Identität ist direkt an die Organisationsnummer geknüpft — ist dieses Feld falsch, schlägt die Zustellung schlicht fehl, unabhängig davon, wie korrekt der Rest der Rechnung ist.', NULL FROM deep_dive_cards d WHERE d.country_id = (SELECT id FROM countries WHERE name_en = 'Norway') AND d.section = 'file_format' AND d.sort_order = 1;
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body)
SELECT d.id, 'fr', 'Identifiants et enregistrement', '[["Schéma de participant","0192 (code ICD pour le organisasjonsnummer norvégien)"],["Abréviation courante","« 0192 » et « NO ORGNR » dans la documentation des fournisseurs"]]', 'L''identité de routage est directement liée au numéro d''organisation — si ce champ est incorrect, la livraison échoue tout simplement, quelle que soit l''exactitude du reste de la facture.', NULL FROM deep_dive_cards d WHERE d.country_id = (SELECT id FROM countries WHERE name_en = 'Norway') AND d.section = 'file_format' AND d.sort_order = 1;
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'file_format', 2 FROM countries WHERE name_en = 'Norway';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body)
SELECT d.id, 'en', 'Mandatory content', '[["Seven required elements","A number and date, both parties, what was supplied, when and where, the price and due date, and any VAT — the VAT stated in kroner."],["Seller''s number plus MVA","The seller gives its name and organisation number, suffixed MVA if VAT-registered. Norway has no separate VAT number."],["Buyer: name plus one ID","A name, and either an address or an organisation number. On reverse-charge sales the buyer''s organisation number is always required."],["Not the VAT Directive","The list comes from Norwegian bookkeeping law, so the Directive''s standard annotations do not apply as such. The format rules are EU-derived."]]', 'The content rule is bokføringsforskriften § 5-1-1 and the parties rule § 5-1-2 — not § 5-1, which is only the sub-chapter heading. Read from a government-hosted copy and Skatteetaten guidance; lovdata.no blocks automated access.', NULL FROM deep_dive_cards d WHERE d.country_id = (SELECT id FROM countries WHERE name_en = 'Norway') AND d.section = 'file_format' AND d.sort_order = 2;
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body)
SELECT d.id, 'es', 'Contenido obligatorio', '[["Siete elementos exigidos","Número y fecha, ambas partes, qué se entregó, cuándo y dónde, el precio y el vencimiento, y el IVA — expresado en coronas."],["Número del vendedor y MVA","El vendedor indica su nombre y número de organización, con el sufijo MVA si está registrado a efectos de IVA. Noruega no tiene un número de IVA aparte."],["Comprador: nombre y un ID","Un nombre, y una dirección o un número de organización. En ventas con inversión del sujeto pasivo el número de organización es siempre obligatorio."],["No es la Directiva del IVA","La lista procede de la ley contable noruega, por lo que las menciones estándar de la Directiva no se aplican como tales. El formato sí deriva de la UE."]]', 'La regla de contenido es bokføringsforskriften § 5-1-1 y la de las partes § 5-1-2 — no § 5-1, que es solo el encabezado del subcapítulo. Leído de una copia alojada por el gobierno y de la guía de Skatteetaten; lovdata.no bloquea el acceso automatizado.', NULL FROM deep_dive_cards d WHERE d.country_id = (SELECT id FROM countries WHERE name_en = 'Norway') AND d.section = 'file_format' AND d.sort_order = 2;
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body)
SELECT d.id, 'de', 'Pflichtangaben', '[["Sieben Pflichtangaben","Nummer und Datum, beide Parteien, was geliefert wurde, wann und wo, Preis und Fälligkeit sowie die Umsatzsteuer — in Kronen angegeben."],["Verkäufernummer plus MVA","Der Verkäufer nennt Namen und Organisationsnummer, mit dem Zusatz MVA bei Umsatzsteuerregistrierung. Norwegen hat keine gesonderte Umsatzsteuernummer."],["Käufer: Name plus eine Kennung","Ein Name sowie eine Adresse oder eine Organisationsnummer. Bei Umkehr der Steuerschuld ist die Organisationsnummer des Käufers stets erforderlich."],["Nicht die Mehrwertsteuerrichtlinie","Die Liste stammt aus dem norwegischen Buchführungsrecht, die Standardvermerke der Richtlinie gelten also nicht als solche. Die Formatregeln sind EU-abgeleitet."]]', 'Die Inhaltsregel ist bokføringsforskriften § 5-1-1, die Parteienregel § 5-1-2 — nicht § 5-1, das nur die Unterkapitelüberschrift ist. Gelesen aus einer staatlich gehosteten Kopie und der Skatteetaten-Anleitung; lovdata.no sperrt automatisierte Zugriffe.', NULL FROM deep_dive_cards d WHERE d.country_id = (SELECT id FROM countries WHERE name_en = 'Norway') AND d.section = 'file_format' AND d.sort_order = 2;
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body)
SELECT d.id, 'fr', 'Mentions obligatoires', '[["Sept éléments exigés","Un numéro et une date, les deux parties, ce qui a été livré, quand et où, le prix et l''échéance, et la TVA — exprimée en couronnes."],["Numéro du vendeur plus MVA","Le vendeur indique son nom et son numéro d''organisation, suivi de MVA s''il est assujetti. La Norvège n''a pas de numéro de TVA distinct."],["Acheteur : nom plus un ID","Un nom, et soit une adresse soit un numéro d''organisation. En autoliquidation, le numéro d''organisation de l''acheteur est toujours exigé."],["Pas la directive TVA","La liste vient du droit comptable norvégien : les mentions standard de la directive ne s''appliquent donc pas comme telles. Le format, lui, dérive de l''UE."]]', 'La règle de contenu est bokføringsforskriften § 5-1-1 et celle des parties § 5-1-2 — pas § 5-1, qui n''est que l''intitulé du sous-chapitre. Lu depuis une copie hébergée par l''État et les instructions de Skatteetaten ; lovdata.no bloque l''accès automatisé.', NULL FROM deep_dive_cards d WHERE d.country_id = (SELECT id FROM countries WHERE name_en = 'Norway') AND d.section = 'file_format' AND d.sort_order = 2;
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'file_format', 3 FROM countries WHERE name_en = 'Norway';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body)
SELECT d.id, 'en', 'Archiving', '[["Two different periods","Five years for primary documentation, but ten for certain specification documents. Storing everything for five is not compliance, and the longer period is the one that gets missed."],["Signature","Not required for the archived copy. Integrity rests on ordinary bookkeeping controls rather than on a certificate."]]', NULL, NULL FROM deep_dive_cards d WHERE d.country_id = (SELECT id FROM countries WHERE name_en = 'Norway') AND d.section = 'file_format' AND d.sort_order = 3;
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body)
SELECT d.id, 'es', 'Conservación', '[["Dos plazos distintos","Cinco años para la documentación primaria, pero diez para ciertos documentos de especificación. Guardarlo todo cinco años no es cumplir, y el plazo largo es el que se pasa por alto."],["Firma","No exigida para la copia archivada. La integridad descansa en los controles contables ordinarios, no en un certificado."]]', NULL, NULL FROM deep_dive_cards d WHERE d.country_id = (SELECT id FROM countries WHERE name_en = 'Norway') AND d.section = 'file_format' AND d.sort_order = 3;
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body)
SELECT d.id, 'de', 'Aufbewahrung', '[["Zwei verschiedene Fristen","Fünf Jahre für die Primärdokumentation, aber zehn für bestimmte Spezifikationsunterlagen. Alles fünf Jahre aufzubewahren ist keine Erfüllung; übersehen wird die längere Frist."],["Signatur","Für die archivierte Kopie nicht erforderlich. Die Integrität stützt sich auf gewöhnliche Buchführungskontrollen, nicht auf ein Zertifikat."]]', NULL, NULL FROM deep_dive_cards d WHERE d.country_id = (SELECT id FROM countries WHERE name_en = 'Norway') AND d.section = 'file_format' AND d.sort_order = 3;
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body)
SELECT d.id, 'fr', 'Conservation', '[["Deux durées différentes","Cinq ans pour la documentation primaire, mais dix pour certains documents de spécification. Tout garder cinq ans n''est pas se conformer, et c''est la durée longue que l''on oublie."],["Signature","Non exigée pour la copie archivée. L''intégrité repose sur les contrôles comptables ordinaires, non sur un certificat."]]', NULL, NULL FROM deep_dive_cards d WHERE d.country_id = (SELECT id FROM countries WHERE name_en = 'Norway') AND d.section = 'file_format' AND d.sort_order = 3;
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'file_format', 4 FROM countries WHERE name_en = 'Norway';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body)
SELECT d.id, 'en', 'Who is in, and who is out', '[["Scope","Same EHF requirements as Norwegian companies"],["Trigger","Local bookkeeping obligations under the Norwegian Bookkeeping Act"],["Small sole proprietorships","Turnover below NOK 50,000, if not VAT-registered"],["B2C","Explicitly excluded from the mandate"]]', 'A foreign entity holding Norwegian bookkeeping obligations gets no lighter version of the duty. A separate B2C e-receipts framework is being assessed by Skattedirektoratet — worth watching, but not part of this reform.', NULL FROM deep_dive_cards d WHERE d.country_id = (SELECT id FROM countries WHERE name_en = 'Norway') AND d.section = 'file_format' AND d.sort_order = 4;
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body)
SELECT d.id, 'es', 'Quién entra y quién queda fuera', '[["Alcance","Los mismos requisitos EHF que las empresas noruegas"],["Desencadenante","Obligaciones contables locales conforme a la Ley de Contabilidad noruega"],["Pequeñas empresas individuales","Facturación inferior a 50.000 NOK, si no están registradas a efectos de IVA"],["B2C","Explícitamente excluido del mandato"]]', 'Una entidad extranjera con obligaciones contables noruegas no obtiene una versión más ligera del deber. Skattedirektoratet evalúa por separado un marco de recibos electrónicos B2C: algo a vigilar, pero que no forma parte de esta reforma.', NULL FROM deep_dive_cards d WHERE d.country_id = (SELECT id FROM countries WHERE name_en = 'Norway') AND d.section = 'file_format' AND d.sort_order = 4;
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body)
SELECT d.id, 'de', 'Wer erfasst ist und wer nicht', '[["Umfang","Dieselben EHF-Anforderungen wie für norwegische Unternehmen"],["Auslöser","Lokale Buchführungspflichten nach dem norwegischen Buchführungsgesetz"],["Kleine Einzelunternehmen","Umsatz unter 50.000 NOK, sofern nicht umsatzsteuerpflichtig registriert"],["B2C","Ausdrücklich von der Pflicht ausgenommen"]]', 'Ein ausländisches Unternehmen mit norwegischen Buchführungspflichten erhält keine abgeschwächte Fassung der Pflicht. Skattedirektoratet prüft gesondert einen Rahmen für B2C-E-Belege — beobachtenswert, aber nicht Teil dieser Reform.', NULL FROM deep_dive_cards d WHERE d.country_id = (SELECT id FROM countries WHERE name_en = 'Norway') AND d.section = 'file_format' AND d.sort_order = 4;
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body)
SELECT d.id, 'fr', 'Qui est concerné, et qui ne l''est pas', '[["Périmètre","Mêmes exigences EHF que pour les entreprises norvégiennes"],["Déclencheur","Obligations comptables locales au titre de la loi norvégienne sur la comptabilité"],["Petites entreprises individuelles","Chiffre d''affaires inférieur à 50 000 NOK, si non assujetties à la TVA"],["B2C","Explicitement exclu de l''obligation"]]', 'Une entité étrangère soumise à des obligations comptables norvégiennes n''obtient aucune version allégée de l''obligation. Skattedirektoratet évalue séparément un cadre de reçus électroniques B2C : à surveiller, mais hors de cette réforme.', NULL FROM deep_dive_cards d WHERE d.country_id = (SELECT id FROM countries WHERE name_en = 'Norway') AND d.section = 'file_format' AND d.sort_order = 4;

