SELECT d.id, 'en', 'Identifiers & registration', '[["Peppol scheme","0245 — SG:DIC"],["Identifier","10-digit Slovak Tax ID (DIČ)"],["Issued by","Financial Administration of the Slovak Republic"]]', 'Use scheme 0245 when registering Slovak end users on the Peppol network — this is the identifier that resolves to a specific recipient''s DIČ for routing purposes.', NULL FROM deep_dive_cards d WHERE d.country_id = (SELECT id FROM countries WHERE name_en = 'Slovakia') AND d.section = 'file_format' AND d.sort_order = 1;
