SELECT d.id, 'fr', 'Identifiants et enregistrement', '[["Schéma Peppol","0245 — SG:DIC"],["Identifiant","Numéro fiscal slovaque à 10 chiffres (DIČ)"],["Délivré par","Administration financière de la République slovaque"]]', 'Utilisez le schéma 0245 lors de l''enregistrement des utilisateurs finaux slovaques sur le réseau Peppol — c''est l''identifiant qui se résout au DIČ d''un destinataire donné à des fins de routage.', NULL FROM deep_dive_cards d WHERE d.country_id = (SELECT id FROM countries WHERE name_en = 'Slovakia') AND d.section = 'file_format' AND d.sort_order = 1;
