INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body)
SELECT d.id, 'en', 'Mandatory content', '[["Full VAT particulars","Supplier and customer with VAT IDs, a sequential number, supply and issue dates, a description, the taxable amount and rate, and the tax in euros."],["Prescribed Slovak wording","Some supplies need set phrases — reverse charge, self-billing, margin schemes. An exempt supply cites the provision that exempts it."],["Simplified invoice limits","Under EUR 100 gross, or EUR 400 on an e-kasa or fuel-pump receipt, the customer''s details and the net unit price may be left out."],["Electronic changes nothing","An electronic invoice carries the same particulars. The 2027 mandate changes the format and the route, not what must be stated."]]', 'The EUR 400 receipt limit has applied since 1 January 2025, replacing an earlier EUR 1,000 cash and EUR 1,600 card split. Read from Financial Administration guidance; slov-lex could not serve the consolidated § 74.', NULL FROM deep_dive_cards d WHERE d.country_id = (SELECT id FROM countries WHERE name_en = 'Slovakia') AND d.section = 'file_format' AND d.sort_order = 2;
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body)
SELECT d.id, 'es', 'Contenido obligatorio', '[["Menciones completas de IVA","Proveedor y cliente con NIF-IVA, número secuencial, fechas de entrega y emisión, una descripción, la base y el tipo, y la cuota en euros."],["Fórmulas eslovacas prescritas","Algunas operaciones exigen frases fijas: inversión del sujeto pasivo, autofacturación, regímenes de margen. Una operación exenta cita la disposición que la exime."],["Límites de factura simplificada","Por debajo de 100 EUR brutos, o 400 EUR en un ticket de e-kasa o surtidor, pueden omitirse los datos del cliente y el precio unitario neto."],["Lo electrónico no cambia nada","Una factura electrónica lleva las mismas menciones. El mandato de 2027 cambia el formato y la vía, no lo que debe constar."]]', 'El límite de 400 EUR para tickets rige desde el 1 de enero de 2025, y sustituyó a un reparto anterior de 1.000 EUR en efectivo y 1.600 EUR con tarjeta. Tomado de la guía de la Administración Financiera; slov-lex no pudo servir el § 74 consolidado.', NULL FROM deep_dive_cards d WHERE d.country_id = (SELECT id FROM countries WHERE name_en = 'Slovakia') AND d.section = 'file_format' AND d.sort_order = 2;
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body)
SELECT d.id, 'de', 'Pflichtangaben', '[["Vollständige USt-Angaben","Lieferant und Kunde mit USt-IdNr., fortlaufende Nummer, Liefer- und Ausstellungsdatum, eine Beschreibung, Bemessungsgrundlage und Satz sowie die Steuer in Euro."],["Vorgeschriebene slowakische Formeln","Manche Umsätze verlangen feste Formulierungen: Umkehr der Steuerschuld, Gutschrift, Margenbesteuerung. Ein steuerfreier Umsatz nennt die befreiende Vorschrift."],["Grenzen der Kleinbetragsrechnung","Unter 100 EUR brutto, oder 400 EUR auf einem e-kasa- oder Zapfsäulenbeleg, dürfen Kundendaten und Nettoeinzelpreis entfallen."],["Elektronisch ändert nichts","Eine elektronische Rechnung trägt dieselben Angaben. Das Mandat 2027 ändert Format und Weg, nicht den erforderlichen Inhalt."]]', 'Die Belegsgrenze von 400 EUR gilt seit dem 1. Januar 2025 und löste die frühere Aufteilung in 1.000 EUR bar und 1.600 EUR per Karte ab. Aus der Anleitung der Finanzverwaltung; slov-lex konnte den konsolidierten § 74 nicht ausliefern.', NULL FROM deep_dive_cards d WHERE d.country_id = (SELECT id FROM countries WHERE name_en = 'Slovakia') AND d.section = 'file_format' AND d.sort_order = 2;
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body)
SELECT d.id, 'fr', 'Mentions obligatoires', '[["Mentions TVA complètes","Fournisseur et client avec numéros de TVA, un numéro séquentiel, les dates de livraison et d''émission, une description, la base et le taux, et la taxe en euros."],["Formules slovaques prescrites","Certaines opérations exigent des formules fixes : autoliquidation, autofacturation, régimes de la marge. Une opération exonérée cite la disposition qui l''exonère."],["Limites de la facture simplifiée","En dessous de 100 EUR TTC, ou de 400 EUR sur un ticket e-kasa ou de pompe, les données du client et le prix unitaire hors taxe peuvent être omis."],["L''électronique ne change rien","Une facture électronique porte les mêmes mentions. Le mandat de 2027 change le format et le circuit, pas ce qui doit y figurer."]]', 'Le plafond de 400 EUR pour les tickets s''applique depuis le 1er janvier 2025 et a remplacé un partage antérieur de 1 000 EUR en espèces et 1 600 EUR par carte. Établi d''après les instructions de l''Administration financière ; slov-lex n''a pas pu servir le § 74 consolidé.', NULL FROM deep_dive_cards d WHERE d.country_id = (SELECT id FROM countries WHERE name_en = 'Slovakia') AND d.section = 'file_format' AND d.sort_order = 2;
