INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body)
SELECT d.id, 'en', 'Archiving', '[["Retention","10 years, original XML format"],["Issuance deadline (until 2030)","15 days from the tax point"],["Issuance deadline (from 2030)","Shortens to 10 days"]]', 'Sending the invoice through a Digital Postman within the deadline is what fulfils the issuance obligation — the clock is on transmission, not just generation.', NULL FROM deep_dive_cards d WHERE d.country_id = (SELECT id FROM countries WHERE name_en = 'Slovakia') AND d.section = 'file_format' AND d.sort_order = 3;
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body)
SELECT d.id, 'es', 'Conservación', '[["Conservación","10 años, en formato XML original"],["Plazo de emisión (hasta 2030)","15 días desde el devengo"],["Plazo de emisión (desde 2030)","Se reduce a 10 días"]]', 'Enviar la factura a través de un Digital Postman dentro del plazo es lo que cumple la obligación de emisión — el plazo se cuenta desde la transmisión, no solo desde la generación.', NULL FROM deep_dive_cards d WHERE d.country_id = (SELECT id FROM countries WHERE name_en = 'Slovakia') AND d.section = 'file_format' AND d.sort_order = 3;
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body)
SELECT d.id, 'de', 'Aufbewahrung', '[["Aufbewahrung","10 Jahre, im ursprünglichen XML-Format"],["Ausstellungsfrist (bis 2030)","15 Tage ab dem Steuertatbestand"],["Ausstellungsfrist (ab 2030)","Verkürzt sich auf 10 Tage"]]', 'Der Versand der Rechnung über einen Digital Postman innerhalb der Frist erfüllt die Ausstellungspflicht — die Frist läuft ab der Übermittlung, nicht nur ab der Erstellung.', NULL FROM deep_dive_cards d WHERE d.country_id = (SELECT id FROM countries WHERE name_en = 'Slovakia') AND d.section = 'file_format' AND d.sort_order = 3;
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body)
SELECT d.id, 'fr', 'Conservation', '[["Conservation","10 ans, au format XML d''origine"],["Délai d''émission (jusqu''en 2030)","15 jours à compter du fait générateur"],["Délai d''émission (à partir de 2030)","Réduit à 10 jours"]]', 'L''envoi de la facture via un Digital Postman dans le délai imparti est ce qui satisfait l''obligation d''émission — le délai court à partir de la transmission, pas seulement de la génération.', NULL FROM deep_dive_cards d WHERE d.country_id = (SELECT id FROM countries WHERE name_en = 'Slovakia') AND d.section = 'file_format' AND d.sort_order = 3;
