INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body)
SELECT d.id, 'en', 'What''s explicitly excluded', '[["PDFs / scanned images","Not treated as e-invoices"],["B2C transactions","Out of scope"],["Other exemptions","Classified information; certain government bodies"]]', 'The FAQ document (9/DPH/2025) is explicit: an e-invoice is defined as a machine-readable structured XML file, full stop — nothing that merely looks like an invoice qualifies.', NULL FROM deep_dive_cards d WHERE d.country_id = (SELECT id FROM countries WHERE name_en = 'Slovakia') AND d.section = 'file_format' AND d.sort_order = 4;
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body)
SELECT d.id, 'es', 'Lo que queda expresamente excluido', '[["PDF / imágenes escaneadas","No se consideran facturas electrónicas"],["Transacciones B2C","Fuera de alcance"],["Otras exenciones","Información clasificada; ciertos organismos públicos"]]', 'El documento de preguntas frecuentes (9/DPH/2025) es explícito: una factura electrónica se define como un archivo XML estructurado legible por máquina, sin más — nada que simplemente parezca una factura cualifica.', NULL FROM deep_dive_cards d WHERE d.country_id = (SELECT id FROM countries WHERE name_en = 'Slovakia') AND d.section = 'file_format' AND d.sort_order = 4;
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body)
SELECT d.id, 'de', 'Was ausdrücklich ausgeschlossen ist', '[["PDFs / gescannte Bilder","Gelten nicht als E-Rechnungen"],["B2C-Transaktionen","Nicht im Anwendungsbereich"],["Weitere Ausnahmen","Verschlusssachen; bestimmte Behörden"]]', 'Das FAQ-Dokument (9/DPH/2025) ist eindeutig: Eine E-Rechnung ist als maschinenlesbare strukturierte XML-Datei definiert, Punkt — alles, was nur wie eine Rechnung aussieht, zählt nicht.', NULL FROM deep_dive_cards d WHERE d.country_id = (SELECT id FROM countries WHERE name_en = 'Slovakia') AND d.section = 'file_format' AND d.sort_order = 4;
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body)
SELECT d.id, 'fr', 'Ce qui est explicitement exclu', '[["PDF / images scannées","Ne sont pas considérées comme des factures électroniques"],["Transactions B2C","Hors champ"],["Autres exemptions","Informations classifiées ; certains organismes publics"]]', 'Le document FAQ (9/DPH/2025) est explicite : une facture électronique est définie comme un fichier XML structuré lisible par machine, un point c''est tout — tout ce qui ressemble simplement à une facture ne suffit pas.', NULL FROM deep_dive_cards d WHERE d.country_id = (SELECT id FROM countries WHERE name_en = 'Slovakia') AND d.section = 'file_format' AND d.sort_order = 4;

